// Auto-generated icon builder — runs before dist:win
// Embeds all icon sizes as base64 PNGs and constructs a valid ICO binary
const fs = require('fs');
const path = require('path');

const PNGS = [
  {
    "size": 16,
    "data": ""
  },
  {
    "size": 32,
    "data": ""
  },
  {
    "size": 48,
    "data": ""
  },
  {
    "size": 64,
    "data": ""
  },
  {
    "size": 128,
    "data": ""
  },
  {
    "size": 256,
    "data": ""
  }
];

function buildIco(pngs) {
  const NUM = pngs.length;
  const bufs = pngs.map(p => Buffer.from(p.data, 'base64'));
  const dataOffset0 = 6 + NUM * 16;
  const header = Buffer.alloc(6, 0);
  header.writeUInt16LE(0, 0);
  header.writeUInt16LE(1, 2);
  header.writeUInt16LE(NUM, 4);
  const dirEntries = [];
  let offset = dataOffset0;
  for (let i = 0; i < NUM; i++) {
    const sz = pngs[i].size;
    const buf = bufs[i];
    const e = Buffer.alloc(16, 0);
    e.writeUInt8(sz === 256 ? 0 : sz, 0);
    e.writeUInt8(sz === 256 ? 0 : sz, 1);
    e.writeUInt8(0, 2);
    e.writeUInt8(0, 3);
    e.writeUInt16LE(1, 4);
    e.writeUInt16LE(32, 6);
    e.writeUInt32LE(buf.length, 8);
    e.writeUInt32LE(offset, 12);
    dirEntries.push(e);
    offset += buf.length;
  }
  return Buffer.concat([header, ...dirEntries, ...bufs]);
}

const outPath = path.join(__dirname, '..', 'assets', 'icon.ico');
fs.mkdirSync(path.dirname(outPath), { recursive: true });
const ico = buildIco(PNGS);
fs.writeFileSync(outPath, ico);
console.log('icon.ico generated (' + ico.length + ' bytes) at', outPath);
